```rust
/// A tap-gesture modifier (SwiftUI `onTapGesture`). Declares the pointer
/// down/up listeners and stores the app-side callback.
#[derive(Clone)]
pub struct TapGesture(Rc<RefCell<dyn FnMut() + 'static>>);

impl PartialEq for TapGesture {
    fn eq(&self, other: &Self) -> bool {
        Rc::ptr_eq(&self.0, &other.0)
    }
}

impl core::fmt::Debug for TapGesture {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.write_str("TapGesture(..)")
    }
}

impl ViewModifier for TapGesture {
    fn apply(&self, node: &mut Node) {
        // Declare the raw pointer listeners the renderer must attach, then store
        // the callback in the app-side gesture list.
        let existing = node
            .properties
            .get(&property_id::EVENT_LISTENERS)
            .copied()
            .unwrap_or(0);
        node.properties.insert(
            property_id::EVENT_LISTENERS,
            existing | pathland_opcode::listener::POINTER_DOWN | pathland_opcode::listener::POINTER_UP,
        );
        node.gestures.push(Gesture::Tap(self.0.clone()));
    }
}
```

Wait, `Modified<V, M>` derives `Debug, Clone, PartialEq` requiring M: Debug + Clone + PartialEq. TapGesture implements all three (Clone derive, PartialEq manual, Debug manual). Good.

But `ViewModifier` requires the modifier type. `TapGesture` is a tuple struct wrapping Rc. It's fine.

