Now time: caller supplies `now` in the same unit as max_duration. Use u64 ms. Default max_distance = 10.0 logical px? and max_duration = 500ms. I'll expose a constructor with defaults and setters, or a Default impl.

Let me write:
```rust
use pathland_opcode::Event;

pub struct TapRecognizer {
    down: Option<DownState>,
    max_distance: f32,
    max_duration: u64,
}

struct DownState {
    target: u32,
    x: f32,
    y: f32,
    time: u64,
}

impl Default for TapRecognizer {
    fn default() -> Self {
        Self::new()
    }
}

impl TapRecognizer {
    pub fn new() -> Self {
        Self { down: None, max_distance: 10.0, max_duration: 500 }
    }
    pub fn with_limits(max_distance: f32, max_duration_ms: u64) -> Self { ... }

    pub fn feed(&mut self, event: &Event, now_ms: u64) -> Option<u32> {
        match event {
            Event::PointerDown { target, x, y, .. } => {
                self.down = Some(DownState { target: *target, x: *x, y: *y, time: now_ms });
                None
            }
            Event::PointerUp { target, x, y, .. } => {
                let mut tapped = None;
                if let Some(d) = self.down.take() {
                    if d.target == *target
                        && (now_ms - d.time) <= self.max_duration
                        && distance(d.x, d.y, *x, *y) <= self.max_distance
                    {
                        tapped = Some(*target);
                    }
                }
                tapped
            }
            Event::PointerMove { target, x, y, leaving, .. } => {
                if let Some(d) = self.down {
                    if *leaving || *target != d.target || distance(d.x, d.y, *x, *y) > self.max_distance {
                        self.down = None;
                    }
                }
                None
            }
            _ => None,
        }
    }

    pub fn reset(&mut self) { self.down = None; }
}

fn distance(x0: f32, y0: f32, x1: f32, y1: f32) -> f32 {
    let dx = x1 - x0;
    let dy = y1 - y0;
    (dx*dx + dy*dy).sqrt()
}
```

Note: PointerMove leaves the `down` state untouched if within slop (so a small jitter doesn't cancel). Good.

Also, `now_ms - d.time` could underflow if now < d.time (u64). To be safe use `now_ms.saturating_sub(d.time)`.

