        if (e.isPointerUp()) {
            int t = downTarget;
            downTarget = -1;
            if (t == e.target && (nowMs - downTimeMs) <= maxDurationMs
                    && distanceSq(downX, downY, e.x(), e.y()) <= maxDistance*maxDistance) {
