        if (e.isPointerMove()) {
            if (downTarget >= 0 && (e.isLeaving() || e.target != downTarget
                    || distanceSq(downX, downY, e.x(), e.y()) > maxDistance*maxDistance)) {
                downTarget = -1;
            }
        }
        return -1;
    }

    private static float distanceSq(float x0, float y0, float x1, float y1) {
